/**
 * These "tests" are in here and don't actually run because importing this file into a test file
 * gums up the test runner.
 */
describe('large API definition', () => {
    it('defines 8000 endpoints keyed by path', () => {
        assert.strictEquals(Object.keys(largeApi.endpoints).length, 8000);
    });

    it('defines 2000 web sockets keyed by path', () => {
        assert.strictEquals(Object.keys(largeApi.webSockets).length, 2000);
    });

    it('exposes endpoints under their declared paths', () => {
        assert.isDefined(largeApi.endpoints['/reports/item-0']);
        assert.isDefined(largeApi.endpoints['/reports/item-1']);
        assert.isDefined(largeApi.endpoints['/reports/item-4000']);
        assert.isDefined(largeApi.endpoints['/reports/item-7999']);
    });

    it('exposes web sockets under their declared paths', () => {
        assert.isDefined(largeApi.webSockets['/ws/stream-0']);
        assert.isDefined(largeApi.webSockets['/ws/stream-1000']);
        assert.isDefined(largeApi.webSockets['/ws/stream-1999']);
    });

    it('preserves path on each stored endpoint', () => {
        const endpoint = largeApi.endpoints['/reports/item-0'];
        assert.isDefined(endpoint);
        assert.strictEquals(endpoint.path, '/reports/item-0');
    });

    it('preserves path on each stored web socket', () => {
        const socket = largeApi.webSockets['/ws/stream-0'];
        assert.isDefined(socket);
        assert.strictEquals(socket.path, '/ws/stream-0');
    });

    it('preserves request method definitions on stored endpoints', () => {
        const endpoint = largeApi.endpoints['/reports/item-0'];
        assert.isDefined(endpoint);
        assert.isDefined(endpoint.requests[HttpMethod.Post]);
    });

    it('preserves client and host messages on stored web sockets', () => {
        const socket = largeApi.webSockets['/ws/stream-0'];
        assert.isDefined(socket);
        assert.isDefined(socket.clientMessage);
        assert.isDefined(socket.hostMessage);
    });

    it('narrows endpoint path keys to the declared path union', () => {
        assert.tsType<keyof typeof largeApi.endpoints>().notEquals<BaseRoutePath>();
        assert.tsType<'/reports/item-0'>().matches<keyof typeof largeApi.endpoints>();
    });

    it('narrows web socket path keys to the declared path union', () => {
        assert.tsType<keyof typeof largeApi.webSockets>().notEquals<BaseRoutePath>();
        assert.tsType<'/ws/stream-0'>().matches<keyof typeof largeApi.webSockets>();
    });
});
